/**
 * Wrap \p that instance recursively with the enhancement produced by the \p factory.
 *
 * The factory decides itself whether it will produce an enhancement for
 * \p that instance, or not. Even if no enhancement has been produced for \p that
 * instance, we will still continue to enhance the instances referenced
 * by \p that instance recursively.
 *
 * \param that instance to wrap
 * \param factory to selectively produce an enhancement
 * \return enhanced \p that instance
 * \throw std::logic_error if \p that instance has been already wrapped.
 * \tparam E type of the enhancement
 */
///@{

template <typename E>
std::shared_ptr<
  types::IClass
> Wrap(
  const std::shared_ptr<
    types::IClass
  >& that,
  const std::function<
    std::shared_ptr<E>(
      const std::shared_ptr<types::IClass>&
    )
  >& factory
) {
  impl::AssertNotEnhanced<
    E,
    types::IClass
  >(that);

  switch (that->model_type()) {
    case types::ModelType::kLangString:
      return impl::WrapLangString<E>(
        std::dynamic_pointer_cast<
          types::ILangString
        >(that),
        factory
      );
      break;
    case types::ModelType::kLangStringSet:
      return impl::WrapLangStringSet<E>(
        std::dynamic_pointer_cast<
          types::ILangStringSet
        >(that),
        factory
      );
      break;
    case types::ModelType::kIecContent:
      return impl::WrapIecContent<E>(
        std::dynamic_pointer_cast<
          types::IIecContent
        >(that),
        factory
      );
      break;
    case types::ModelType::kOtherContent:
      return impl::WrapOtherContent<E>(
        std::dynamic_pointer_cast<
          types::IOtherContent
        >(that),
        factory
      );
      break;
    case types::ModelType::kSpecification:
      return impl::WrapSpecification<E>(
        std::dynamic_pointer_cast<
          types::ISpecification
        >(that),
        factory
      );
      break;
    case types::ModelType::kSomething:
      return impl::WrapSomething<E>(
        std::dynamic_pointer_cast<
          types::ISomething
        >(that),
        factory
      );
      break;
    default:
      throw std::invalid_argument(
        common::Concat(
          "Unexpected model type: ",
          std::to_string(
            static_cast<std::uint32_t>(
              that->model_type()
            )
          )
        )
      );
      break;
  }
}

